## Building a Mad Libs Generator

### The Template

```xiom
fn generate_story(noun: Str, verb: Str, adjective: Str, place: Str) -> Str {
  let mut story = "The ";
  story = string.str_concat(story, adjective);
  story = string.str_concat(story, " ");
  story = string.str_concat(story, noun);
  story = string.str_concat(story, " ");
  story = string.str_concat(story, verb);
  story = string.str_concat(story, "ed to the ");
  story = string.str_concat(story, place);
  story = string.str_concat(story, ".");
  story
}
```

### A Better Approach: Replace Tokens

```xiom
fn mad_libs(template: Str, noun: Str, verb: Str, adj: Str) -> Str {
  let mut result = "";
  let mut i = 0;
  while i < template.len() {
    let chunk = read_until_token(template, &mut i);
    result = string.str_concat(result, chunk);

    if i < template.len() {
      let token = read_token(template, &mut i);
      if token == "NOUN" {
        result = string.str_concat(result, noun);
      } else if token == "VERB" {
        result = string.str_concat(result, verb);
      } else if token == "ADJ" {
        result = string.str_concat(result, adj);
      };
    };
  };
  result
}
```

