use xiom.io;

use xiom.string;
fn mad_libs(adjective: Str, noun: Str, verb: Str, adverb: Str) -> Str {
  var story = "The ";
  story = string.str_concat(story, adjective);
  story = string.str_concat(story, " ");
  story = string.str_concat(story, noun);
  story = string.str_concat(story, " ");
  story = string.str_concat(story, verb);
  story = string.str_concat(story, "s ");
  story = string.str_concat(story, adverb);
  story = string.str_concat(story, " every day.");
  story
}

fn main() -> Int {
  io.println(mad_libs("sparkly", "unicorn", "dance", "gracefully"));
  io.println(mad_libs("grumpy", "dragon", "sleep", "loudly"));
  io.println(mad_libs("tiny", "robot", "compute", "tirelessly"));
  return 0;
}
